-- name: kubernetes_operator__cancel_shared_tests :exec
UPDATE control_plane.integration_connection_tests test SET state='CANCELLED',version=test.version+1,completed_at=clock_timestamp(),safe_error_code='KUBERNETES_OPERATOR_SOURCE_CHANGED' FROM control_plane.integration_connections connection JOIN control_plane.integration_broker_identity_revisions identity ON identity.id=connection.broker_identity_revision_id AND identity.organization_id=connection.organization_id WHERE test.connection_id=connection.id AND test.organization_id=connection.organization_id AND identity.purpose='KUBERNETES_TARGET' AND test.state='DUE';
